// Parse CSV binary data into wine row objects
const items = $input.all();
const results = [];

for (const item of items) {
  const binaryKey = Object.keys(item.binary || {})[0];
  if (!binaryKey) continue;

  const csvText = Buffer.from(item.binary[binaryKey].data, 'base64').toString('utf-8');
  const lines = csvText.split(/\r?\n/).filter(l => l.trim());
  if (lines.length < 2) continue;

  // Detect delimiter
  const delim = lines[0].includes('\t') ? '\t' : ',';

  const parseRow = (line) => {
    const result = [];
    let cur = '';
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const ch = line[i];
      if (ch === '"') {
        if (inQuotes && line[i+1] === '"') { cur += '"'; i++; }
        else inQuotes = !inQuotes;
      } else if (ch === delim && !inQuotes) {
        result.push(cur.trim()); cur = '';
      } else {
        cur += ch;
      }
    }
    result.push(cur.trim());
    return result;
  };

  const headers = parseRow(lines[0]).map(h => h.toLowerCase().replace(/[^a-z0-9]/g, '_'));

  // Column name aliases from common export formats (CellarTracker, Vivino, manual)
  const alias = {
    'wine':               'wine_name',
    'name':               'wine_name',
    'wine_name':          'wine_name',
    'loc':                'location',
    'location':           'location',
    'bin':                'bin',
    'size':               'bottle_size',
    'bottle_size':        'bottle_size',
    'qty':                'quantity',
    'quantity':           'quantity',
    'in_stock':           'quantity',
    'my_score':           'score_personal',
    'score_personal':     'score_personal',
    'ct_score':           'score_community',
    'community_score':    'score_community',
    'score_community':    'score_community',
    'drinkability':       'score_drinkability',
    'score_drinkability': 'score_drinkability',
    'drink_from':         'drink_window_start',
    'drink_window_start': 'drink_window_start',
    'begin':              'drink_window_start',
    'drink_until':        'drink_window_end',
    'drink_window_end':   'drink_window_end',
    'end':                'drink_window_end',
    'type':               'wine_type',
    'wine_type':          'wine_type',
    'varietal':           'variety',
    'variety':            'variety',
    'master_varietal':    'variety',
    'vintage':            'vintage',
    'year':               'vintage',
    'producer':           'producer',
    'price':              'price_paid',
    'price_paid':         'price_paid',
    'value':              'value_score',
    'value_score':        'value_score',
    'region':             'region',
    'sub_region':         'sub_region',
    'subregion':          'sub_region',
    'appellation':        'sub_region',
    'store':              'store',
    'purchase_date':      'purchase_date',
    'purchased':          'purchase_date'
  };

  const numericFields = new Set(['quantity','score_personal','score_community','score_drinkability','drink_window_start','drink_window_end','vintage','price_paid','value_score']);

  for (let i = 1; i < lines.length; i++) {
    const cols = parseRow(lines[i]);
    const row = {};
    headers.forEach((h, idx) => {
      const mapped = alias[h];
      if (!mapped) return;
      let val = cols[idx] || null;
      if (val === '' || val === 'N/A' || val === 'n/a') val = null;
      if (val !== null && numericFields.has(mapped)) {
        const n = parseFloat(val);
        val = isNaN(n) ? null : n;
      }
      row[mapped] = val;
    });
    if (row.wine_name) results.push({ json: row });
  }
}

return results;

// Build summary after all files processed
const items = $input.all();
let totalRows = 0;
for (const item of items) {
  if (Array.isArray(item.json)) totalRows += item.json.length;
  else totalRows += 1;
}
return [{ json: { summary: `CellarTracker sync complete. ${totalRows} wine records upserted.`, timestamp: new Date().toISOString(), count: totalRows } }];
